<?php
declare(strict_types=1);require_once __DIR__.'/bootstrap.php';learning_require_login();$uid=learning_user_id();$rows=learning_courses_with_progress($uid);function ep2($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
